inline const Wave& wave(int shape) noexcept { return waves[(size_t)std::clamp(shape,0,15)]; }
inline Bounds bounds(int shape) noexcept { return wave(shape).bounds; }
inline double delta(int shape,float slopePercent) noexcept {
    const auto b=bounds(shape);const double p=std::clamp(std::isfinite(slopePercent)?double(slopePercent):0.,-100.,100.)*.01;
    return p*(p<0?b.start-b.outerStart:b.outerEnd-b.end);
}
inline double value(const Polynomial& p,double u) noexcept { return p.c0+u*(p.c1+u*(p.c2+u*p.c3)); }
inline double derivative(const Polynomial& p,double u) noexcept { return p.c1+u*(2*p.c2+3*u*p.c3); }
inline double xAt(const Segment& p,double d,double u) noexcept { return value(p.x,u)+d*value(p.shift,u); }
inline float node(int shape,int index,float slopePercent) noexcept {
    const auto& w=wave(shape);const double d=delta(shape,slopePercent);
    double x=double(index&8191)/8192.;const double origin=xAt(w.segments[0],d,0);
    if(x<origin)x+=1;else if(x>=origin+1)x-=1;
    // Segment endpoints are monotone even when controls meet at the limits.
    int low=0,high=w.count-1;
    while(low<high){const int middle=(low+high)/2;
        if(x>=xAt(w.segments[(size_t)middle],d,1))low=middle+1;else high=middle;}
    const auto& s=w.segments[(size_t)low];const double a=xAt(s,d,0),b=xAt(s,d,1);
    if(b-a<=1.e-15)return float(std::clamp(value(s.y,1),0.,1.));
    double left=0,right=1,u=std::clamp((x-a)/(b-a),0.,1.);
    // Fixed upper bound; typical inversion converges in4..6 iterations.
    // Bracketing covers zero tangents and coincident endpoint controls.
    for(int iteration=0;iteration<20;++iteration){
        const double error=xAt(s,d,u)-x;
        if(std::abs(error)<=1.e-13)break;
        if(error<0)left=u;else right=u;
        const double dx=derivative(s.x,u)+d*derivative(s.shift,u);
        const double next=dx>1.e-15?u-error/dx:(left+right)*.5;
        u=std::isfinite(next)&&next>left&&next<right?next:(left+right)*.5;
    }
    return float(std::clamp(value(s.y,u),0.,1.));
}
